css:
.lockup { position: absolute; left: 50%; transform-origin: 50% 50%; white-space: nowrap; }
.row { display: block; line-height: 1; }
.row.lead { text-align: left; padding-left: 4%; }
.row.tail { text-align: right; padding-right: 4%; }
.row.hero { text-align: center; }
.row.line { text-align: center; line-height: 1.1; }
.w { display: inline-block; white-space: pre; color: #fff; text-shadow: 0 2px 18px rgba(0,0,0,.42); will-change: transform, filter, opacity; }
.w.hero { color: transparent; -webkit-background-clip: text; background-clip: text; text-shadow: none; padding: 0.06em 0.06em 0.1em; margin: 0 -0.06em; }

js:
// Mixed-type caption lockups (design pass test): one lockup per phrase, key word behind the person.
// Each lockup: look, lead words, hero words, tail words, each word [text, time].
const LOCKUPS = [
  { look: "geo", start: 0.0, end: 1.96, lead: [["Tu", 0.0], ["n'as", 0.4], ["pas", 0.5], ["besoin", 0.98], ["d'", 1.18]], hero: [["extension", 1.18]] },
  { look: "serif", start: 1.96, end: 3.2, lead: [["pas", 2.04], ["besoin", 2.1], ["de", 2.32]], hero: [["faux-cils,", 2.44]] },
  { look: "geo", start: 3.2, end: 4.44, lead: [["pas", 3.3], ["besoin", 3.36], ["de", 3.56]], hero: [["mascara", 4.0]] },
  { look: "line", start: 4.44, end: 6.2, words: [["t'as", 4.44], ["besoin", 4.54], ["de", 4.74], ["juste", 4.9], ["une", 5.18], ["chose.", 5.52]] },
  { look: "wide", start: 6.2, end: 7.7, lead: [["Le", 6.26]], hero: [["LASH", 6.52], ["LIFT", 7.0]] },
  { look: "serif", start: 7.7, end: 9.76, lead: [["On", 7.74], ["va", 7.94], ["aller", 8.14], ["chercher", 8.34], ["la", 8.6]], hero: [["courbure", 8.98]], tail: [["de", 9.42], ["ton,", 9.54]] },
  { look: "geo", start: 9.76, end: 12.2, lead: [["de", 9.76], ["la", 10.14], ["longueur", 10.44], ["de", 10.84], ["ton", 10.98]], hero: [["cil", 11.1], ["naturel", 11.36]] },
  { look: "script", start: 12.2, end: 13.6, lead: [["On", 12.24], ["va", 12.36], ["l'", 12.54]], hero: [["allonger", 12.54]] },
  { look: "line", start: 13.6, end: 16.2, words: [["en", 14.32], ["ayant", 14.7], ["une", 15.0], ["courbure", 15.2]] },
  { look: "line", start: 16.2, end: 17.3, words: [["qui", 16.22], ["fait", 16.44], ["qu'on", 16.62], ["va", 16.9], ["chercher", 17.1]] },
  { look: "wide", start: 17.3, end: 19.9, lead: [["le", 17.32]], hero: [["100 %", 17.5]], tail: [["potentiel", 17.94], ["de", 18.72], ["ton", 19.12], ["cil.", 19.28]], tailSerif: true },
];
const PINK = "#F06AC8", PINK_LIGHT = "#FFC4EE", VIOLET = "#A774F2";
const LOOK = {
  geo: { hero: "font: 800 VAR px Poppins; letter-spacing: -0.02em;", grad: [PINK_LIGHT, PINK], lead: "font: 300 LVpx Poppins;", tail: "font: 300 LVpx Poppins;" },
  serif: { hero: "font: italic 900 VAR px 'Playfair Display'; letter-spacing: -0.01em;", grad: [VIOLET, PINK], lead: "font: italic 700 LVpx Inter;", tail: "font: italic 700 TVpx 'Playfair Display';" },
  wide: { hero: "font: italic 800 VAR px Archivo; font-stretch: 125%; letter-spacing: -0.01em;", grad: [PINK, PINK], lead: "font: italic 300 LVpx Inter;", tail: "font: italic 700 TVpx 'Playfair Display';" },
  script: { hero: "font: 800 VAR px Poppins; letter-spacing: -0.02em;", grad: [PINK_LIGHT, PINK], lead: "font: 400 LVpx 'Great Vibes';", tail: "font: 300 LVpx Poppins;" },
};
const HEAD_Y = 650;
const els = [];

window.init = async () => {
  // Fonts load on first use: load every face before measuring anything.
  await Promise.all(["800 100px Poppins", "300 100px Poppins", "italic 900 100px 'Playfair Display'", "italic 700 100px 'Playfair Display'", "italic 700 100px Inter", "italic 300 100px Inter", "italic 800 100px Archivo", "400 100px 'Great Vibes'"].map((f) => document.fonts.load(f)));
  const stage = document.getElementById("stage");
  for (const l of LOCKUPS) {
    const box = document.createElement("div");
    box.className = "lockup";
    stage.appendChild(box);
    const item = { l, box, words: [] };
    const span = (parent, text, t, css, cls = "") => {
      const s = document.createElement("span");
      s.className = `w ${cls}`;
      s.textContent = text;
      s.style.cssText = css;
      parent.appendChild(s);
      item.words.push({ s, t, hero: cls.includes("hero") });
      return s;
    };
    if (l.look === "line") {
      const row = document.createElement("div");
      row.className = "row line";
      box.appendChild(row);
      l.words.forEach(([w, t], i) => span(row, (i ? " " : "") + w, t, "font: italic 700 72px Inter;"));
      box.style.top = `${HEAD_Y + 170}px`;
      els.push(item);
      continue;
    }
    const look = LOOK[l.look];
    // Size the key word to ~74% of the width (capped), measured in a scratch span.
    const probe = document.createElement("span");
    probe.style.cssText = look.hero.replace("VAR px", "100px") + "position:absolute;visibility:hidden;white-space:nowrap";
    probe.textContent = l.hero.map((h) => h[0]).join(" ");
    stage.appendChild(probe);
    const w100 = probe.getBoundingClientRect().width;
    probe.remove();
    const cap = l.look === "serif" ? 270 : l.look === "wide" ? 190 : 230;
    const S = Math.min(cap, Math.max(92, (100 * 800) / w100));
    const LV = Math.round(Math.min(72, Math.max(46, S * (l.look === "serif" ? 0.4 : 0.34))));
    const TV = Math.round(Math.max(54, S * 0.46));
    const lead = document.createElement("div");
    lead.className = "row lead" + (l.look === "script" ? " script" : "");
    const hero = document.createElement("div");
    hero.className = "row hero behind";
    const tail = document.createElement("div");
    tail.className = "row tail";
    box.append(lead, hero, tail);
    const leadCss = look.lead.replace("LV", l.look === "script" ? Math.round(S * 0.62) : LV);
    (l.lead ?? []).forEach(([w, t], i) => span(lead, (i && !/'$/.test(l.lead[i - 1][0]) ? " " : "") + w, t, leadCss));
    const heroCss = look.hero.replace("VAR px", `${Math.round(S)}px`);
    const heroSpans = l.hero.map(([w, t], i) => span(hero, (i ? " " : "") + w, t, heroCss, "hero"));
    const tailCss = (l.tailSerif ? LOOK.serif.tail : look.tail).replace("TV", TV).replace("LV", LV);
    (l.tail ?? []).forEach(([w, t], i) => span(tail, (i ? " " : "") + w, t, tailCss));
    // One gradient across the whole key word, even when it's two words.
    const hw = hero.getBoundingClientRect().width;
    const x0 = hero.getBoundingClientRect().left;
    for (const s of heroSpans) {
      s.style.backgroundImage = `linear-gradient(90deg, ${look.grad[0]}, ${look.grad[1]})`;
      s.style.backgroundSize = `${hw}px 100%`;
      s.style.backgroundPosition = `${x0 - s.getBoundingClientRect().left}px 0`;
    }
    lead.style.marginBottom = `${-S * (l.look === "script" ? 0.32 : 0.16)}px`;
    tail.style.marginTop = `${-S * 0.12}px`;
    box.style.top = `${HEAD_Y - box.getBoundingClientRect().height / 2}px`;
    els.push(item);
  }
};

const clamp = (x) => Math.max(0, Math.min(1, x));
window.render = (t) => {
  for (const { l, box, words } of els) {
    const on = t >= l.start && t < l.end;
    box.style.display = on ? "block" : "none";
    if (!on) continue;
    const drift = 1 + 0.025 * clamp((t - l.start) / Math.max(0.6, l.end - l.start));
    box.style.transform = `translateX(-50%) scale(${drift})`;
    for (const w of words) {
      const p = clamp((t - (w.t - 0.04)) / (w.hero ? 0.26 : 0.18));
      const e = M.expoOut(p);
      const size = parseFloat(getComputedStyle(w.s).fontSize);
      w.s.style.opacity = t < w.t - 0.04 ? 0 : e;
      const blur = (1 - e) * Math.min(36, size * (w.hero ? 0.16 : 0.12));
      w.s.style.filter = w.hero ? `blur(${blur.toFixed(1)}px) drop-shadow(0 3px 10px rgba(0,0,0,.22))` : `blur(${blur.toFixed(1)}px)`;
      w.s.style.transform = `translateY(${((1 - e) * size * 0.06).toFixed(1)}px) scale(${1 + (w.hero ? 0.12 : 0.08) * (1 - e)})`;
    }
  }
};
